public List<LetterSource> getFlatList() {
    ArrayList<LetterSource> flattened = new ArrayList<>();
    for (List<LetterSource> letterSources : values()) {
      flattened.addAll(letterSources);
    }
    Collections.sort(flattened, COMPARATOR);
    return flattened;
  }
